package android.graphics;public class Typeface {public static final int NORMAL=0,BOLD=1;public final java.awt.Font font;Typeface(java.awt.Font f){font=f;}public static final Typeface DEFAULT=new Typeface(new java.awt.Font(java.awt.Font.SANS_SERIF,java.awt.Font.PLAIN,1)),SANS_SERIF=DEFAULT,SERIF=new Typeface(new java.awt.Font(java.awt.Font.SERIF,java.awt.Font.PLAIN,1)),MONOSPACE=new Typeface(new java.awt.Font(java.awt.Font.MONOSPACED,java.awt.Font.PLAIN,1));public static Typeface create(Typeface family,int style){return new Typeface(family.font.deriveFont(style==BOLD?java.awt.Font.BOLD:java.awt.Font.PLAIN));}public static Typeface createFromFile(java.io.File file){try{return new Typeface(java.awt.Font.createFont(java.awt.Font.TRUETYPE_FONT,file));}catch(Exception e){throw new RuntimeException(e);}}}
